package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class ConnectorActionsBrowserAcceptance {
    static void run(BrowserTest h)throws Exception{
        try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h.store,h.store.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
            var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/operations");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Configure and run outbound actions")).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Create connector action")).press("Enter");page.getByLabel("Action name").fill("Reviewed external browser action");page.getByLabel("Connection alias").fill(endpoint.provider.alias);page.getByLabel("HTTP method").selectOption("PATCH");page.getByLabel("Fixed endpoint path").fill("/write");var inputs=List.of(CatalogueQuestionsAcceptance.question("title","string",true,List.of()),CatalogueQuestionsAcceptance.question("size","choice",true,List.of("Small","Large")),CatalogueQuestionsAcceptance.question("ready","boolean",true,List.of()),CatalogueQuestionsAcceptance.question("date","date",true,List.of()),CatalogueQuestionsAcceptance.question("count","integer",true,List.of()));page.getByLabel("Input definitions (JSON)").fill(JSON.writeValueAsString(inputs));page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save connector action")).press("Enter");page.waitForURL(java.util.regex.Pattern.compile(".*/admin/connector-actions/[0-9a-f]{32}"));assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Reviewed external browser action").setExact(true))).isVisible();page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Run this action")).press("Enter");page.getByLabel("Question title (required)").fill("Exact browser input <script>");page.getByLabel("Question size (required)").selectOption("Small");page.getByLabel("Question ready (required)").selectOption("false");page.getByLabel("Question date (required)").fill("2026-11-20");page.getByLabel("Question count (required)").fill("2");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Review external request")).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Confirm external request"))).isVisible();assertThat(page.locator("main")).containsText("Exact browser input <script>");assertThat(page.locator("main script")).hasCount(0);assertEquals(0,endpoint.calls.get());
            for(String theme:List.of("light","dark")){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.checkAccessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/connector-action-"+theme+".png")).setFullPage(true));}
            endpoint.status.set(503);page.getByLabel("Send this reviewed external request").check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Queue external action")).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Background work details"))).isVisible();String receipt=page.url();try(var db=h.store.open()){db.update("UPDATE os_work SET created_at=? WHERE job_id=?",Long.MIN_VALUE,receipt.substring(receipt.lastIndexOf('/')+1));db.connection.commit();}new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000);page.reload();assertThat(page.locator("main")).containsText("failed");assertEquals(1,endpoint.calls.get());assertEquals("PATCH",endpoint.method.get());page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Record external reconciliation")).press("Enter");page.getByLabel("External outcome").selectOption("not_applied");page.getByLabel("Evidence note").fill("Verified with external receipt EX-42 <script>");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record reconciliation")).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Recorded reconciliation"))).isVisible();assertThat(page.locator("main")).containsText("EX-42 <script>");assertThat(page.locator("main script")).hasCount(0);new Store(h.store.environment);page.reload();assertThat(page.locator("main")).containsText("not_applied");ReleaseBrowserAcceptance.checkAccessible(page);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to execution receipt")).press("Enter");assertEquals(receipt,page.url());assertEquals(1,endpoint.calls.get());
        }
    }
}
